import { test, expect } from '@playwright/test';

test.describe('Image Upload from Clipboard', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should allow pasting an image into the upload area', async ({ page }) => {
    const uploadArea = page.getByRole('textbox', { name: /upload area/i });

    await uploadArea.focus();
    await page.evaluate(() => {
      const img = new Image();
      img.src = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAUA...'; // Base64 image data
      const clipboardData = new ClipboardEvent('').clipboardData || new DataTransfer();
      clipboardData.setData('text/html', `<img src="${img.src}">`);
      return clipboardData;
    });

    await page.keyboard.press('Control+V');

    const uploadedImage = page.getByRole('img', { name: /uploaded image/i });
    await expect(uploadedImage).toBeVisible();
  });

  test('should display an error message when pasting a non-image', async ({ page }) => {
    const uploadArea = page.getByRole('textbox', { name: /upload area/i });

    await uploadArea.focus();
    await page.evaluate(() => {
      const clipboardData = new ClipboardEvent('').clipboardData || new DataTransfer();
      clipboardData.setData('text/plain', 'This is not an image');
      return clipboardData;
    });

    await page.keyboard.press('Control+V');

    const errorMessage = page.getByText(/invalid file type/i);
    await expect(errorMessage).toBeVisible();
  });
});
